import { expect, test } from 'bun:test';
import { dedupe, seeded } from '../src/order';

test('shuffled input matches the expected list', () => {
  const shuffled = ['c', 'a', 'b'];
  // end-to-end exact-list assertion of a shuffled set whose order is not contractual
  expect(dedupe(shuffled)).toEqual(['c', 'a', 'b']);
});

test('seeded order is reproducible', () => {
  // an explicit contractual order: same seed must give the same exact sequence
  expect(seeded(4, 7)).toEqual(seeded(4, 7));
});

