export const dedupe = (xs: string[]) => {
  const seen = new Set<string>();
  const out: string[] = [];
  for (const x of xs) if (!seen.has(x)) { seen.add(x); out.push(x); }
  return out;
};
export const seeded = (count: number, seed: number) => {
  let x = seed;
  return Array.from({ length: count }, (_, i) => ((x = (x * 1103515245 + 12345) & 0x7fffffff), `item-${(x + i) % count}`));
};
